#!/usr/bin/env bash
# Prints the Homebrew formula for a released version.
# Usage: homebrew-formula.sh VERSION SHA256_OF_THE_MACOS_TARBALL
set -euo pipefail

version=$1
sha256=$2

cat <<EOF
# Generated by .github/workflows/release.yml; do not edit by hand.
class Gicio < Formula
  desc "Review huge changes, such as an AI agent's branch, step by step with AI assist"
  homepage "https://github.com/synek317/gicio"
  url "https://github.com/synek317/gicio/releases/download/v${version}/gicio-${version}-aarch64-apple-darwin.tar.gz"
  sha256 "${sha256}"
  license "PolyForm-Noncommercial-1.0.0"

  depends_on arch: :arm64
  depends_on :macos

  def install
    bin.install "gicio"
  end

  test do
    assert_match "Usage: gicio", shell_output("#{bin}/gicio --help")
  end
end
EOF
